use super::*;
fn campaign()->Value{let p=std::env::var_os("Z_PRIVATE_CAMPAIGN").map(std::path::PathBuf::from).unwrap_or_else(||std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../dist/original/campaign.json"));serde_json::from_slice(&std::fs::read(p).unwrap()).unwrap()}
fn controlled_pack()->Value{let mut disk=vec![[0u8;26];12];for d in &mut disk{d[..2].copy_from_slice(&(-1i16).to_le_bytes());}for(at,n)in[(0,400i16),(2,500),(4,144),(6,64)]{disk[0][at..at+2].copy_from_slice(&n.to_le_bytes());}let headers=bridge::HEADERS.iter().enumerate().map(|(i,p)|{let mut b=vec![0;1280];b[0]=4;b[10]=bridge::FRAMES[i];b[11]=bridge::FRAMES[i];json!({"pointer":p,"bytes":b})}).collect::<Vec<_>>();let frames=(0..4).map(|dir|(0..12).map(|f|{let mut rows=vec![[0i16;4];if dir&1==0{6}else{4}];if f==11{rows.last_mut().unwrap()[3]=-1;}rows}).collect::<Vec<_>>()).collect::<Vec<_>>();json!({"nativeBridgeDisk26":disk,"nativeBridgePlaybackHeaders":headers,"nativeCraneBridgeFrames":frames,"nativeCraneBuildFrames":vec![vec![[0i16;4];6];12],"bridges":[{"id":0,"nativeSlot":0,"nativeOrientation":0,"x":800,"y":1000,"w":288,"h":128,"hp":0,"maxHp":600,"nativeFlags15":2}]})}
fn field()->Game{field_for_team(0)}
fn field_for_team(team:i32)->Game{let mut g=Game::new(0,1,985);g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.native_tile_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.bridge_base=vec![-1;4096];g.map.bridge_hp=vec![0.];g.map.bridge_max_hp=vec![600.];g.map.native_road_graph=Some(crate::original_route::RoadGraph{regions:(0..96).map(|_|crate::original_route::RoadRegion{bounds:[0;4],waypoint:0,next:vec![0;96]}).collect()});g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.native_world=None;g.native_group_rosters.clear();g.ai_teams.clear();g.import_native_world(&controlled_pack());g.spawn("crane",team,800.,900.,1,None);g.maintain_native_group_rosters();g}
#[test]fn native_bridge_metadata_reload_retains_unowned_bytes_but_resets_all_jobs_and_exact_file_prefix(){let mut g=field();let s=g.native_world.as_mut().unwrap();s.bridges[0].raw_tail[19]=171;s.bridges[0].raw_tail[27]=184;s.bridges[0].raw_tail[31]=199;s.trail.jobs[63].0.fill(255);s.trail.bridge_headers[0].1[11]=1;s.trail.bridge_headers[0].1.extend([77,78,79]);g.import_native_world(&controlled_pack());let s=g.native_world.as_ref().unwrap();assert_eq!((s.bridges[0].raw_tail[19],s.bridges[0].raw_tail[27],s.bridges[0].raw_tail[31]),(171,184,199));assert!(s.trail.jobs.iter().all(|j|j.0==[0;24]));assert_eq!(s.trail.bridge_headers[0].1[11],27);assert_eq!(&s.trail.bridge_headers[0].1[1280..],&[77,78,79]);assert_eq!(s.bridges.len(),12);}
#[test]fn native_bridge_last_job_controls_completion_and_legacy_max_sync_cannot_preempt_it(){let mut g=field();assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(true));let mut s=g.native_world.take().unwrap();let b=&mut s.bridges[0];b.record.hp=601;b.raw_tail[16]=2;b.record.flags15=0x2e;g.native_world=Some(s);g.map.bridge_hp[0]=601.;g.sync_native_world();assert_eq!(g.native_world.as_ref().unwrap().bridges[0].record.flags15,0x2e);assert!(g.finish_native_bridge_job(bridge::BASE));let b=&g.native_world.as_ref().unwrap().bridges[0];assert_eq!((b.record.hp,b.raw_tail[16],b.record.flags15),(601,1,0x2e));assert!(g.finish_native_bridge_job(bridge::BASE));let b=&g.native_world.as_ref().unwrap().bridges[0];assert_eq!((b.record.hp,b.raw_tail[16],b.record.flags15),(600,0,0));assert!(!b.native_work_owned);}
#[test]fn native_bridge_arrival_uses_shared_partial_capacity_and_consumes_seed_even_when_full(){for free in[0usize,1,63,64]{let mut g=field();assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(true));let slot=g.units[0].native_slot.unwrap();let c=g.native_world.as_ref().unwrap().cranes[slot].as_ref().unwrap().clone();for(i,j)in g.native_world.as_mut().unwrap().trail.jobs.iter_mut().enumerate(){j.set_ptr(0,if i<free{0}else{bridge::HEADERS[0]});j.0[13]=171;j.0[23]=199;}let mut rng=g.original_rng.clone();rng.next_u32();g.create_native_bridge_jobs(0,&c);let s=g.native_world.as_ref().unwrap();let expected=7.min(free);assert_eq!(s.bridges[0].raw_tail[16],expected as u8);assert_eq!(g.original_rng.words,rng.words);assert_eq!(s.trail.jobs.iter().filter(|j|j.ptr(4)==bridge::BASE).count(),expected);assert!(s.trail.jobs.iter().all(|j|j.0[13]==171&&j.0[23]==199));assert_eq!(s.bridges[0].record.flags15&2,2);}}
#[test]fn native_bridge_death_releases_actual_target_and_fresh_same_slot_reuse_cannot_keep_crane_binding(){let mut g=field();assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(true));let slot=g.units[0].native_slot.unwrap();assert_eq!(g.native_selection.contexts[slot].link28,Some(bridge::BASE));g.units[0].native_initiative_scan.flags71|=16;g.native_world.as_mut().unwrap().bridges[0].record.flags15|=12;assert!(g.native_remove_actor(0,true,false));assert_eq!(g.native_world.as_ref().unwrap().bridges[0].record.flags15&12,0);g.spawn("grunt",0,800.,900.,2,None);let i=g.units.len()-1;assert_eq!(g.units[i].native_slot,Some(slot));assert!(g.native_world.as_ref().unwrap().cranes[slot].is_none());assert_eq!(g.native_world.as_ref().unwrap().bridges[0].record.flags15&2,2);}
#[test]fn native_bridge_accepted_browser_orders_use_native_work_and_last_job_for_both_teams_and_modes(){for team in[0,1]{for mp in[false,true]{let mut g=field_for_team(team);g.multiplayer=mp;let id=g.units[0].id;g.command(&json!({"kind":"repairBridge","ids":[id],"team":team,"x":864,"y":1040}));assert!(g.owns_native_bridge_repair(0));assert_eq!(g.units[0].native_order5c,1);let slot=g.units[0].native_slot.unwrap();let c=g.native_world.as_ref().unwrap().cranes[slot].as_ref().unwrap().clone();let w=g.native_hardware_pool[g.units[0].native_hardware_slot.unwrap()].attributes;let rate=w.byte(6);let increment=i16::from(rate>>4);assert!(increment>0);let callbacks=(601+increment-1)/increment;for _ in 1..callbacks{assert!(!g.progress_native_bridge_crane(0,rate));}assert!(g.progress_native_bridge_crane(0,rate));assert_eq!(g.map.bridge_hp[0],f64::from(-1+callbacks*increment));assert_ne!(g.native_world.as_ref().unwrap().bridges[0].record.flags15&2,0);g.create_native_bridge_jobs(0,&c);for _ in 0..45{g.update_native_building_trails(0);}assert_eq!(g.map.bridge_hp[0],600.);assert_eq!(g.native_world.as_ref().unwrap().bridges[0].record.flags15&2,0);}}}
#[test]fn native_bridge_rejects_non_destroyed_partial_hull_and_missing_data_keeps_legacy_adapter(){let mut g=field();g.native_world.as_mut().unwrap().bridges[0].record.flags15=0;g.native_world.as_mut().unwrap().bridges[0].record.hp=500;assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(false));assert_eq!(g.units[0].native_order5c,0);g.native_world.as_mut().unwrap().bridge_repair_ready=false;assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),None);g.map.native_road_graph=None;assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),None);}
#[test]fn native_bridge_does_not_require_unrelated_six_layer_building_crane_metadata(){let mut g=field();g.native_world.as_mut().unwrap().crane_frames.clear();assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(true));g.units[0].native_phase35=59;assert!(g.update_native_crane_building(0,0,0));assert_ne!(g.native_world.as_ref().unwrap().trail.boundary,Some(trail::Boundary{address:0x495644,length:48}));}
#[test]fn native_bridge_shared_late_jobs_survive_actual_crane_removal_after_retreat(){let mut g=field();assert_eq!(g.begin_native_bridge_after_browser_acceptance(0,[432,520]),Some(true));let slot=g.units[0].native_slot.unwrap();let c=g.native_world.as_ref().unwrap().cranes[slot].as_ref().unwrap().clone();g.native_world.as_mut().unwrap().bridges[0].record.hp=601;g.create_native_bridge_jobs(0,&c);let before=g.native_world.as_ref().unwrap().trail.jobs;assert!(g.native_remove_actor(0,true,false));assert_eq!(g.native_world.as_ref().unwrap().trail.jobs,before,"58ec0 must not cancel already-born shared playback jobs");for _ in 0..45{g.update_native_building_trails(0);}let s=g.native_world.as_ref().unwrap();assert!(s.trail.jobs.iter().all(|j|j.ptr(0)==0));assert_eq!((s.bridges[0].record.hp,s.bridges[0].raw_tail[16],s.bridges[0].record.flags15&2),(600,0,0));}
#[test]#[ignore="private49 original bridge inputs/19 destroyed mission bridges"]
fn all_nineteen_authored_destroyed_bridges_use_work_finite_retreat_and_late_last_job_in_both_modes(){
 let data=campaign();let mut cases=0;let mut samples=vec![];
 for mp in[false,true]{for mission in data["missions"].as_array().unwrap(){for target in mission["bridges"].as_array().unwrap().iter().filter(|b|b["initiallyDestroyed"]==true){let mut m=mission.clone();let width=m["map"]["width"].as_u64().unwrap()as usize;let height=m["map"]["height"].as_u64().unwrap()as usize;let mut pair=None;
  'bank:for cell in target["tiles"].as_array().unwrap(){let k=cell.as_u64().unwrap()as usize;let(tx,ty)=(k%width,k/width);for dy in -3i32..=3{for dx in -3i32..=3{let(x,y)=(tx as i32+dx,ty as i32+dy);if x<1||y<1||x>=width as i32-1||y>=height as i32-1{continue;}let j=y as usize*width+x as usize;let tile=m["map"]["tiles"][j].as_u64().unwrap();let code=m["map"]["terrainCodes"][j].as_u64().unwrap()&127;if !matches!(tile,0|1)||!matches!(code,0|7|51){continue;}let p=[f64::from(x)*32.+16.,f64::from(y)*32.+16.];let click=[tx as f64*32.+16.,ty as f64*32.+16.];if(p[0]-click[0]).hypot(p[1]-click[1])>100.||m["buildings"].as_array().unwrap().iter().any(|b|b["hp"].as_f64().unwrap()>0.&&p[0]>b["x"].as_f64().unwrap()&&p[0]<b["x"].as_f64().unwrap()+b["w"].as_f64().unwrap()&&p[1]>b["y"].as_f64().unwrap()&&p[1]<b["y"].as_f64().unwrap()+b["h"].as_f64().unwrap()){continue;}pair=Some((p,click));break 'bank;}}}
  let(p,click)=pair.expect("legal bank in original map");m["spawns"]=json!([{"type":"crane","team":0,"x":p[0],"y":p[1],"squad":1},{"type":"gatling","team":1,"x":32,"y":32,"squad":2}]);for s in m["sectors"].as_array_mut().unwrap(){s["owner"]=json!(-1);}for b in m["buildings"].as_array_mut().unwrap(){b["team"]=json!(-1);b["product"]=Value::Null;}
  let number=m["number"].as_u64().unwrap();let mut g=Game::new(number as usize-1,1,985);g.multiplayer=mp;g.apply_original(&m).unwrap();g.ai_teams.clear();g.maintain_native_group_rosters();for i in 1..g.units.len(){if let Some(slot)=g.units[i].native_slot{g.native_group_rosters.members[slot].as_mut().unwrap().flags69|=64;}}
  let id=g.units[0].id;let us=g.units[0].native_slot.unwrap();let bid=target["id"].as_u64().unwrap()as usize;let bs=g.native_world.as_ref().unwrap().bridges.iter().position(|b|b.binding==bid).unwrap();assert!(g.native_world.as_ref().unwrap().bridge_repair_ready);g.command(&json!({"kind":"repairBridge","ids":[id],"team":0,"x":click[0],"y":click[1]}));assert!(g.owns_native_bridge_repair(0));assert_eq!(g.units[0].native_order5c,1);
  let(mut work,mut retreat,mut jobs,mut art,mut late)=(false,false,false,false,false);let mut repaired=false;let(mut work_rows,mut reverse_rows,mut late_rows)=(vec![],vec![],vec![]);for tick in 0..3500{g.winner=None;g.step(0.059);let s=g.native_world.as_ref().unwrap();let b=&s.bridges[bs];let c=s.cranes[us].as_ref().unwrap();work|=b.record.hp>=0;retreat|=c.work9a==254;jobs|=s.trail.jobs.iter().any(|j|j.ptr(0)!=0&&j.ptr(4)==bridge::BASE+b.native_slot as u32*32);art|=g.native_display_queue().iter().any(|r|r["source"]=="craneWork");late|=!s.trail_draws.is_empty();repaired=b.record.flags15&2==0;let rows=g.native_display_queue().into_iter().filter(|r|r["source"]=="craneWork").collect::<Vec<_>>();if c.frame86<12&&!rows.is_empty()&&work_rows.is_empty(){work_rows=rows.clone();}if c.frame86>=64&&!rows.is_empty()&&reverse_rows.is_empty(){reverse_rows=rows;}if !s.trail_draws.is_empty()&&late_rows.is_empty(){late_rows=s.trail_draws.clone();}
   if std::env::var_os("Z_BRIDGE_TRACE").is_some()&&tick%100==0{eprintln!("BRIDGE m={number} id={bid} mp={mp} tick={tick} xy={:?} phase={} order5c={} order={} work={} f86={} b1={:?} hp={} flags={} pending={} path={} remain={} goal={:?} route={:?} trail={:?}",(g.units[0].x,g.units[0].y),g.units[0].native_phase35,g.units[0].native_order5c,g.units[0].order,c.work9a,c.frame86,c.approach_b1,b.record.hp,b.record.flags15,b.raw_tail[16],g.units[0].path.len(),g.units[0].native_remaining48,g.units[0].dest,g.native_route_boundary,s.trail.boundary);}
   if repaired{break;}}
  assert!(work&&retreat&&jobs&&art&&late&&repaired,"m{number} bridge{bid} mp{mp}: work={work} retreat={retreat} jobs={jobs} art={art} late={late} repaired={repaired}");let b=&g.native_world.as_ref().unwrap().bridges[bs];assert_eq!((b.record.hp,b.raw_tail[16]),(600,0));assert_eq!(b.record.flags15&0x2e,0);assert_eq!(g.map.bridge_hp[bid],600.);samples.push(json!({"mission":number,"bridge":bid,"mp":mp,"work":work_rows,"reverse":reverse_rows,"late":late_rows}));cases+=1;
 }}}
 assert_eq!(cases,38);if let Some(path)=std::env::var_os("Z_BRIDGE_ROWS"){std::fs::write(path,serde_json::to_vec(&samples).unwrap()).unwrap();}
}
